import { Agent, GameEngine } from "../game";
import { BTNode, Selector, Sequence, Condition, Action } from "../behaviorTree";
import { STANDARD_AI_PROFILE, BTDef } from "../../data/ai_profiles";
import { BTConditions, BTActions } from "../ai/BTRegistry";
import { NodeState } from "../../types";

export class AISystem {

    // The new entry point using the Data-Driven Builder
    public buildAI(a: Agent, engine: GameEngine): BTNode {
        // In the future, we can load different profiles based on Agent Role
        // e.g. const profile = AI_DB[a.role] || STANDARD_AI_PROFILE;
        return this.parseNode(STANDARD_AI_PROFILE, engine);
    }

    private parseNode(def: BTDef, engine: GameEngine): BTNode {
        let node: BTNode;

        switch (def.type) {
            case 'SELECTOR':
                node = new Selector(def.name);
                if (def.children) {
                    def.children.forEach(childDef => {
                        node.add(this.parseNode(childDef, engine));
                    });
                }
                break;

            case 'SEQUENCE':
                node = new Sequence(def.name);
                if (def.children) {
                    def.children.forEach(childDef => {
                        node.add(this.parseNode(childDef, engine));
                    });
                }
                break;

            case 'CONDITION':
                const condFn = def.key ? BTConditions[def.key] : null;
                if (!condFn) {
                    console.warn(`AI Builder: Missing Condition Key '${def.key}'`);
                    // Fallback to avoid crash
                    node = new Condition(def.name, () => false); 
                } else {
                    node = new Condition(def.name, (agent: Agent) => condFn(agent, engine, def.args));
                }
                break;

            case 'ACTION':
                const actFn = def.key ? BTActions[def.key] : null;
                if (!actFn) {
                    console.warn(`AI Builder: Missing Action Key '${def.key}'`);
                    // Fallback
                    node = new Action(def.name, () => NodeState.FAILURE); // Failure
                } else {
                    node = new Action(def.name, (agent: Agent) => actFn(agent, engine, def.args));
                }
                break;

            default:
                throw new Error(`Unknown BT Node Type: ${(def as any).type}`);
        }

        return node;
    }
}

import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    // Config
    private bloomThreshold = 200;
    private bloomIntensity = 1.5;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number) {
        // Resize buffer if needed
        if (this.tempCanvas.width !== width || this.tempCanvas.height !== height) {
            this.tempCanvas.width = width;
            this.tempCanvas.height = height;
        }

        // 1. Copy current frame to buffer
        this.tempCtx.clearRect(0, 0, width, height);
        this.tempCtx.drawImage(ctx.canvas, 0, 0);

        // 2. Chromatic Aberration (Glitch Effect based on Trauma)
        if (trauma > 0) {
            const offset = trauma * 10;
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.5 * trauma;

            // Red Channel Shift
            ctx.drawImage(this.tempCanvas, -offset, 0);

            // Blue Channel Shift
            ctx.drawImage(this.tempCanvas, offset, 0);

            ctx.restore();
        }

        // 3. Fake Bloom (High-pass brightness + Blur)
        // Since real gaussian blur is expensive in 2D Canvas, we simulate it via downscaling 
        // or just overlaying "light" pixels using 'lighter' blend mode multiple times.
        // For performance, we'll use a simplified Glow pass.

        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.filter = 'blur(8px)'; // CSS Filter (hardware accelerated in modern browsers)
        ctx.globalAlpha = 0.4;
        ctx.drawImage(this.tempCanvas, 0, 0);

        // Extra bloom for high intensity moments
        if (trauma > 0.5) {
            ctx.filter = 'blur(16px)';
            ctx.globalAlpha = 0.3 * trauma;
            ctx.drawImage(this.tempCanvas, 0, 0);
        }
        ctx.restore();

        // 4. Scanlines (Retro Tactical Feel)
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = 'rgba(0,0,0,0.1)';
        // We simulate scanlines with a pattern or just fill
        // Here we just do a vignette boost
        const vig = ctx.createRadialGradient(width/2, height/2, height*0.4, width/2, height/2, height);
        vig.addColorStop(0, 'transparent');
        vig.addColorStop(1, 'rgba(0,10,20,0.4)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, width, height);
        ctx.restore();

        // 5. Flash (High Trauma)
        if (trauma > 0.8) {
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = `rgba(255,255,255,${(trauma - 0.8)})`;
            ctx.fillRect(0, 0, width, height);
            ctx.restore();
        }
    }
}

import { Vector } from "../utils";

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (For Smooth Interpolation)
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;
    private focusSpeed: number = 5.0; // Lerp speed
    private isLocked: boolean = false; // If true, overrides manual pan

    // Trauma System (0.0 to 1.0)
    private trauma: number = 0;

    // Config
    private maxShakeOffset: number = 15;   
    private maxShakeAngle: number = 0.02; 

    // Current Frame Shake Values
    private currentShakeX: number = 0;
    private currentShakeY: number = 0;
    private currentShakeRot: number = 0;

    constructor() {}

    public sync(camera: Camera) {
        // If not locked by cinematic event, sync with user input
        if (!this.isLocked) {
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
            // Snap immediately if user is controlling
            this.x = camera.x;
            this.y = camera.y;
            this.zoom = camera.zoom;
        }
    }

    // Call this to override manual control for a cinematic moment
    public setFocus(x: number, y: number, zoom: number = 1.5, duration: number = 0) {
        this.isLocked = true;
        this.targetX = x;
        this.targetY = y;
        this.targetZoom = zoom;

        if (duration > 0) {
            setTimeout(() => {
                this.isLocked = false;
            }, duration * 1000);
        }
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        // 1. Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 2.0);
        }

        // 2. Calculate Shake (Trauma^2)
        const shakeFactor = this.trauma * this.trauma;
        this.currentShakeX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;

        // 3. Smooth Camera Movement (Cinematic Lerp)
        if (this.isLocked) {
            const t = Math.min(1, dt * this.focusSpeed);
            this.x += (this.targetX - this.x) * t;
            this.y += (this.targetY - this.y) * t;
            this.zoom += (this.targetZoom - this.zoom) * t;
        }
    }

    public applyTransform(ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) {
        // Apply Shake + Position
        const cx = canvasWidth / 2;
        const cy = canvasHeight / 2;

        ctx.translate(cx + this.currentShakeX, cy + this.currentShakeY);
        ctx.rotate(this.currentShakeRot);
        ctx.scale(this.zoom, this.zoom);

        // Camera Panning
        // Adjust for center pivot
        ctx.translate(-this.x - cx / this.zoom, -this.y - cy / this.zoom);
    }

    // Deprecated: Post-processing moved to PostProcessor.ts
    public applyPostProcessing(ctx: CanvasRenderingContext2D, width: number, height: number) {
        // No-op, functionality moved
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Procedural Noise function
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number // NEW: Time injection for animation
    ) {
        const BASE_THICKNESS = 12; 
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.7, baseColor);
            grad.addColorStop(1, '#020617');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // Layer Lines
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        // --- DYNAMIC TEXTURE LOGIC ---
        if (type === 'MAGMA') {
            // Animated Magma Pulse
            const pulse = Math.sin(globalTime * 2.0 + x * 0.05 + y * 0.05); // Spatial offset
            const magColor = pulse > 0 ? '#ef4444' : '#b91c1c'; // Red <-> Dark Red

            const magmaGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
            magmaGrad.addColorStop(0, '#fca5a5'); // Hot Center
            magmaGrad.addColorStop(0.5, magColor);
            magmaGrad.addColorStop(1, '#450a0a'); // Crust Edge

            ctx.fillStyle = magmaGrad;

        } else if (type === 'ICE') {
            // Shimmering Ice
            const shimmer = Math.sin(globalTime * 3.0 + x * 0.1);
            const base = theme.top;
            ctx.fillStyle = shimmer > 0.8 ? '#ffffff' : base;

        } else {
            // Static Gradient
            const topGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
            topGrad.addColorStop(0, theme.rim); 
            topGrad.addColorStop(0.3, theme.top);
            topGrad.addColorStop(1, theme.sideDark); 
            ctx.fillStyle = topGrad;
        }

        ctx.fill();

        // 3. Rim Light
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;

        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];

        ctx.moveTo(x + c4.x, y - topY + c4.y);
        ctx.lineTo(x + c3.x, y - topY + c3.y);
        ctx.lineTo(x + c2.x, y - topY + c2.y); 
        ctx.stroke();

        ctx.globalAlpha = 1.0;

        // 4. Subtle Outline
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.moveTo(x + HEX_CORNERS[2].x, y - topY + HEX_CORNERS[2].y);
        ctx.lineTo(x + HEX_CORNERS[1].x, y - topY + HEX_CORNERS[1].y);
        ctx.lineTo(x + HEX_CORNERS[0].x, y - topY + HEX_CORNERS[0].y);
        ctx.lineTo(x + HEX_CORNERS[5].x, y - topY + HEX_CORNERS[5].y);
        ctx.lineTo(x + HEX_CORNERS[4].x, y - topY + HEX_CORNERS[4].y);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;

        const n = noise(q, r);
        const time = performance.now() / 1000;

        if (type === 'MAGMA') {
            // Emissive Cracks
            const pulse = 0.5 + Math.sin(time * 2 + n * 10) * 0.5;
            ctx.globalAlpha = 0.8 + pulse * 0.2;
            ctx.strokeStyle = '#fef08a'; // Bright yellow cracks
            ctx.lineWidth = 2;
            ctx.shadowColor = '#ef4444';
            ctx.shadowBlur = 10 * pulse;

            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5);
            ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3);
            ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            ctx.shadowBlur = 0;
        } else if (type === 'VOID') {
            // ... existing void logic
            ctx.globalAlpha = 0.2;
            if (n > 0.5) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
                ctx.beginPath(); ctx.arc(cx + 10, cy - 2, 1.5, 0, Math.PI*2); ctx.fill();
            } else if (n < 0.2) {
                ctx.beginPath();
                ctx.rect(cx - 5, cy - 5, 4, 4);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            ctx.globalAlpha = 0.6;
            const tufts = Math.floor(n * 4) + 2;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;
                const wind = Math.sin(time + cx * 0.01) * 2;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind*2, cy + oy - 8);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox + 2 + wind, cy + oy - 5, cx + ox + 4 + wind*2, cy + oy - 7);
                ctx.lineWidth = 1.5;
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.4;
            ctx.fillStyle = '#fff';
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2);
                ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4);
                ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();
                const glint = Math.sin(time * 2 + n * 10);
                if (glint > 0.8) {
                    ctx.globalAlpha = (glint - 0.8) * 2;
                    ctx.fillStyle = '#fff';
                    ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();
                }
            }
        } else if (type === 'DESERT') {
            ctx.globalAlpha = 0.3;
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 5, 20, 0.5, 1.5);
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(cx + 5, cy + 5, 20, 0.5, 1.5);
            ctx.stroke();
        }

        ctx.restore();
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; // NEW

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor; // NEW

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );

        // Trigger Smart Camera for Ultimates
        // Check for specific events that should trigger cinematic focus
        events.forEach(e => {
            if (e.type === 'CAST_START' && e.skill?.tag === 'ULT') {
                const target = engine.agents.find(a => a.id === e.targetId);
                // If it's a unit target, focus on them. If ground, focus on ground.
                if (target) {
                    this.camera.setFocus(target.px, target.py, 1.3, 2.0); // Smooth zoom in
                } else if (e.pos) {
                    this.camera.setFocus(e.pos.x, e.pos.y, 1.3, 2.0);
                }
            }
        });
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        this.camera.sync(camera);
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 8. Top VFX (Particles above everything)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig);

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            ctx.restore(); // Exit Camera Space
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
            ctx.save(); // Dummy save to match restore below
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Exit Camera Space

        // 11. Post Processing (Bloom, Glitch, Vignette)
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        // 12. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: any) {
        // --- 1. Draw Trail ---
        const p = op.proj;
        if (p && p.trail.length > 1) {
            ctx.save();
            if (op.pSkillVis === 'ARROW') {
                ctx.beginPath();
                // To properly draw trail in world space we need history.
                // Since this render is visual only, we skip complex trail for now.
            }
            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const altitude = op.pVisShadowY - op.pVisY;
        if (altitude > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - altitude/400);
            ctx.scale(shadowScale, shadowScale);
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);
        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { Vector, MapConfig, HexUtils } from "../utils";

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current Visual State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (The "Attractor")
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // Cinematic State
    private interestX: number | null = null;
    private interestY: number | null = null;
    private interestTimer: number = 0;

    // Damping Config (The "Weight" of the camera)
    // Lower = Heavier/Slower. Higher = Snappier.
    private readonly PAN_DAMPING = 2.0; 
    private readonly ZOOM_DAMPING = 3.0;

    // Trauma System (Drastically Reduced for Stability)
    private trauma: number = 0;
    private maxShakeOffset: number = 4;   // Reduced from 15 to 4
    private maxShakeAngle: number = 0.005; // Reduced from 0.02 to 0.005

    // Current Frame Shake Values
    private currentShakeX: number = 0;
    private currentShakeY: number = 0;
    private currentShakeRot: number = 0;

    constructor() {}

    // Called every frame to sync with User Input (Mouse/Touch)
    // If we are in a cinematic moment, we ignore user input gently.
    public sync(camera: Camera, mapConfig: MapConfig) {
        // Calculate the "Neutral" center of the map
        const centerHex = { q: Math.floor(mapConfig.w / 2), r: Math.floor(mapConfig.h / 2) };
        const mapCenter = HexUtils.toPx(centerHex.q, centerHex.r, mapConfig);

        if (this.interestTimer > 0 && this.interestX !== null && this.interestY !== null) {
            // --- CINEMATIC MODE ---
            // The target is a weighted blend between the Map Center and the Action Point.
            // We don't want to go 100% to the unit, that's too disorienting.
            // Go 40% towards the unit from center.
            const blend = 0.4;
            this.targetX = mapCenter.x + (this.interestX - mapCenter.x) * blend;
            this.targetY = mapCenter.y + (this.interestY - mapCenter.y) * blend;

            // Gentle zoom in
            this.targetZoom = 1.3; 
        } else {
            // --- MANUAL MODE ---
            // Sync strictly with user input when not doing anything special
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;

            // If user is actively panning (inputs changing drastically), snap to it to feel responsive
            const dist = Math.abs(camera.x - this.x) + Math.abs(camera.y - this.y);
            if (dist > 100) {
                this.x = camera.x;
                this.y = camera.y;
                this.zoom = camera.zoom;
            }
        }
    }

    // Gentle suggestion to look at a point (e.g. Ult cast)
    public setInterestPoint(x: number, y: number, duration: number = 2.0) {
        this.interestX = x;
        this.interestY = y;
        this.interestTimer = duration;
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        // 1. Timer Decay
        if (this.interestTimer > 0) {
            this.interestTimer -= dt;
        }

        // 2. Trauma Decay (Linear)
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 1.5);
        }

        // 3. Calculate Shake (Trauma^2 or ^3 for non-linear falloff)
        // Using Perlin-like noise simulation via Math.sin/cos with time would be smoother,
        // but random * factor is okay if factor is small.
        const shakeFactor = this.trauma * this.trauma;
        this.currentShakeX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;

        // 4. Smooth Damping (The "Rubber Band" effect)
        // x += (target - x) * speed * dt
        // Used logic: Exponential Moving Average for frame-rate independence approximate
        const panFactor = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomFactor = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panFactor;
        this.y += (this.targetY - this.y) * panFactor;
        this.zoom += (this.targetZoom - this.zoom) * zoomFactor;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) {
        const cx = canvasWidth / 2;
        const cy = canvasHeight / 2;

        // 1. Apply Shake (Screen Space)
        // Only translate, avoid rotating the whole screen too much to prevent dizziness
        ctx.translate(this.currentShakeX, this.currentShakeY);

        // Very subtle rotation only at high trauma
        if (this.trauma > 0.5) {
            ctx.translate(cx, cy);
            ctx.rotate(this.currentShakeRot);
            ctx.translate(-cx, -cy);
        }

        // 2. Apply Camera Zoom/Pan
        ctx.translate(cx, cy);
        ctx.scale(this.zoom, this.zoom);
        ctx.translate(-this.x - cx / this.zoom, -this.y - cy / this.zoom);
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );

        // Trigger Soft Camera Focus for Ultimates
        events.forEach(e => {
            if (e.type === 'CAST_START' && e.skill?.tag === 'ULT') {
                const target = engine.agents.find(a => a.id === e.targetId);
                // Use new setInterestPoint for a gentle nudge
                if (target) {
                    this.camera.setInterestPoint(target.px, target.py, 2.5);
                } else if (e.pos) {
                    this.camera.setInterestPoint(e.pos.x, e.pos.y, 2.5);
                }
            }
        });
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Pass mapConfig to sync so camera knows where the center is for damping
        this.camera.sync(camera, engine.mapConfig); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 8. Top VFX (Particles above everything)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig);

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            ctx.restore(); // Exit Camera Space
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
            ctx.save(); // Dummy save to match restore below
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Exit Camera Space

        // 11. Post Processing (Bloom, Glitch, Vignette)
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        // 12. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: any) {
        // --- 1. Draw Trail ---
        const p = op.proj;
        if (p && p.trail.length > 1) {
            ctx.save();
            if (op.pSkillVis === 'ARROW') {
                ctx.beginPath();
                // To properly draw trail in world space we need history.
                // Since this render is visual only, we skip complex trail for now.
            }
            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const altitude = op.pVisShadowY - op.pVisY;
        if (altitude > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - altitude/400);
            ctx.scale(shadowScale, shadowScale);
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);
        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number) {
        // Ensure strictly integer dimensions to avoid sub-pixel blurring
        const w = Math.floor(width);
        const h = Math.floor(height);

        // Resize buffer if needed
        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }

        // 1. Copy current frame to buffer
        // CRITICAL: Clear buffer first to prevent accumulation
        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // 2. Chromatic Aberration (Significantly Toned Down)
        // Only apply if trauma is significant (> 0.1) to avoid constant blur
        if (trauma > 0.1) {
            const offset = Math.floor(trauma * 6); // Hard integer offset

            if (offset > 0) {
                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = 0.4 * trauma;

                // Red Channel Shift
                ctx.drawImage(this.tempCanvas, -offset, 0);

                // Blue Channel Shift
                ctx.drawImage(this.tempCanvas, offset, 0);

                ctx.restore();
            }
        }

        // 3. Bloom / Glow (Optimized)
        // Instead of heavy blur which causes double-vision/ghosting, 
        // we use a very subtle overlay for brightness only.
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';

        // Only bloom really bright parts? 
        // We simulate this by lowering opacity.
        // Removed `filter: blur` because it kills performance and causes ghosting on some high-DPI screens.
        ctx.globalAlpha = 0.15; 
        ctx.drawImage(this.tempCanvas, 0, 0);

        // High intensity bloom only on high trauma
        if (trauma > 0.5) {
            ctx.globalAlpha = 0.2 * trauma;
            ctx.drawImage(this.tempCanvas, 0, 0);
        }
        ctx.restore();

        // 4. Vignette (Dark corners) - Helps focus eye
        ctx.save();
        ctx.globalCompositeOperation = 'multiply'; // Multiply is cleaner for vignette
        const rad = Math.max(w, h) * 0.8;
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.6, w/2, h/2, rad);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,10,20,0.5)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();

        // 5. White Flash (Explosion impact)
        if (trauma > 0.8) {
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = `rgba(255,255,255,${(trauma - 0.8)})`;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }
    }
}

import { MapConfig, HexUtils } from "../utils";

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current Visual State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (The "Attractor")
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // Cinematic State
    private interestX: number | null = null;
    private interestY: number | null = null;
    private interestTimer: number = 0;

    // Damping: Higher = Snappier (Less "floaty")
    private readonly PAN_DAMPING = 8.0; 
    private readonly ZOOM_DAMPING = 5.0;

    // Trauma System
    private trauma: number = 0;
    private maxShakeOffset: number = 5;   
    private maxShakeAngle: number = 0.01; 

    private currentShakeX: number = 0;
    private currentShakeY: number = 0;
    private currentShakeRot: number = 0;

    constructor() {}

    // Force immediate snap (used on init/resize)
    public snapTo(x: number, y: number, zoom: number) {
        this.x = x;
        this.y = y;
        this.zoom = zoom;
        this.targetX = x;
        this.targetY = y;
        this.targetZoom = zoom;
    }

    public sync(camera: Camera, mapConfig: MapConfig, mapKeys: Set<string>) {
        // If user is manually interacting (inputs changing), cancel cinematic
        const dist = Math.abs(camera.x - this.targetX) + Math.abs(camera.y - this.targetY);
        const isUserMoving = dist > 10; // Threshold

        if (isUserMoving) {
            this.interestTimer = 0; // Cancel cinematic
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
        } else if (this.interestTimer > 0 && this.interestX !== null && this.interestY !== null) {
            // --- CINEMATIC GENTLE DRIFT ---
            // Don't center perfectly on the action, just drift slightly towards it
            // This prevents motion sickness.

            const center = this.getMapCenter(mapConfig, mapKeys);

            // Bias: 80% Map Center, 20% Action Point
            const bias = 0.2;
            const destX = center.x + (this.interestX - center.x) * bias;
            const destY = center.y + (this.interestY - center.y) * bias;

            this.targetX = destX - (100 / this.zoom); // Offset slightly to account for HUD
            this.targetY = destY;
            this.targetZoom = Math.max(camera.zoom, 1.2); 
        } else {
            // Default: Sync with React State (User Inputs)
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
        }
    }

    // NEW: Calculate true visual center of the existing map tiles
    public getMapCenter(mapConfig: MapConfig, mapKeys: Set<string>) {
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, mapConfig);
            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (p.y < minY) minY = p.y;
            if (p.y > maxY) maxY = p.y;
            count++;
        });

        if (count === 0) return { x: 0, y: 0 };

        return {
            x: (minX + maxX) / 2,
            y: (minY + maxY) / 2
        };
    }

    public setInterestPoint(x: number, y: number, duration: number = 1.5) {
        // Only set interest if not already shaking heavily (combat chaos)
        if (this.trauma < 0.5) {
            this.interestX = x;
            this.interestY = y;
            this.interestTimer = duration;
        }
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        if (this.interestTimer > 0) this.interestTimer -= dt;

        // Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 2.0);
        }

        // Calculate Shake
        const shakeFactor = this.trauma * this.trauma;
        this.currentShakeX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;

        // Smooth Damping
        const panFactor = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomFactor = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panFactor;
        this.y += (this.targetY - this.y) * panFactor;
        this.zoom += (this.targetZoom - this.zoom) * zoomFactor;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) {
        const cx = canvasWidth / 2;
        const cy = canvasHeight / 2;

        // 1. Shake
        ctx.translate(this.currentShakeX, this.currentShakeY);

        // 2. Rotation (Only at high trauma)
        if (this.trauma > 0.3) {
            ctx.translate(cx, cy);
            ctx.rotate(this.currentShakeRot);
            ctx.translate(-cx, -cy);
        }

        // 3. Camera
        // Pivot around screen center
        ctx.translate(cx, cy);
        ctx.scale(this.zoom, this.zoom);
        ctx.translate(-this.x, -this.y);
    }
}

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        if (!width || !height || width <= 0 || height <= 0) return;

        // --- BOUNDING BOX CALCULATION ---
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (p.y < minY) minY = p.y;
            if (p.y > maxY) maxY = p.y;
            count++;
        });

        // Fallback if map is empty
        if (count === 0) {
            const centerHex = { q: Math.floor(engine.mapConfig.w / 2), r: Math.floor(engine.mapConfig.h / 2) };
            const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
            minX = maxX = p.x;
            minY = maxY = p.y;
        }

        const mapCenterX = (minX + maxX) / 2;
        const mapCenterY = (minY + maxY) / 2;

        // Visual Correction:
        // Maps look better if the "Ground" is slightly lower than center, leaving room for units/UI.
        const visualOffsetY = -BLOCK_HEIGHT * 2; 

        // Target: Place mapCenter at screen center
        // CameraX = MapCenterX 
        // CameraY = MapCenterY
        // (CameraSystem subtracts these, so 0,0 is center of screen relative to camera)

        // Reset Zoom based on map size? Optional. Keeping current zoom for now.
        // camera.current.zoom = 1.0; 

        camera.current.x = mapCenterX;
        camera.current.y = mapCenterY + visualOffsetY;

        // SNAP LOGIC: Inform the smooth camera system to jump instantly
        // This requires accessing the engine's renderer camera system, but since this hook 
        // drives the React ref, we set the initial state here.
        engine.renderer?.camera.snapTo(camera.current.x, camera.current.y, camera.current.zoom);

    }, [engine.mapConfig, engine.mapKeys]); // Re-center when map content changes

    const pan = useCallback((dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        if (dx === 0 && dy === 0) return;

        // Standard pan
        camera.current.x += dx / camera.current.zoom;
        camera.current.y += dy / camera.current.zoom;
    }, []);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    }, []);

    const getScreenCoords = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    }, []);

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom,
        getScreenCoords
    };
};

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );

        // Trigger Soft Camera Focus for Ultimates
        events.forEach(e => {
            if (e.type === 'CAST_START' && e.skill?.tag === 'ULT') {
                const target = engine.agents.find(a => a.id === e.targetId);
                if (target) {
                    this.camera.setInterestPoint(target.px, target.py, 2.5);
                } else if (e.pos) {
                    this.camera.setInterestPoint(e.pos.x, e.pos.y, 2.5);
                }
            }
        });
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Pass mapConfig AND mapKeys to calculate correct center
        this.camera.sync(camera, engine.mapConfig, engine.mapKeys); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 8. Top VFX (Particles above everything)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig);

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            ctx.restore(); // Exit Camera Space
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
            ctx.save(); // Dummy save to match restore below
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Exit Camera Space

        // 11. Post Processing (Bloom, Glitch, Vignette)
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        // 12. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: any) {
        // --- 1. Draw Trail ---
        const p = op.proj;
        if (p && p.trail.length > 1) {
            ctx.save();
            if (op.pSkillVis === 'ARROW') {
                ctx.beginPath();
            }
            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const altitude = op.pVisShadowY - op.pVisY;
        if (altitude > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - altitude/400);
            ctx.scale(shadowScale, shadowScale);
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);
        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex, MovementType, LogActionType } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS, LOG_COLORS } from "../constants";

// Core Entities
import { Agent, SpecialVisualStatus } from "./core/Agent";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { EventBus } from "./events/EventBus";
// Import Renderer Type ONLY (to avoid circular value dependency issue if possible, though strict loop might need loose coupling)
import type { GameRenderer } from "./renderer";

// Re-export for compatibility
export { Agent, SpecialVisualStatus };

export class GameEngine {
    public agents: Agent[] = [];

    // Delegated to MapSystem
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }

    // Delegated to CombatSystem (Single Source of Truth)
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];

    // NEW: Central Event Bus
    public bus: EventBus = new EventBus();

    // Weak reference to renderer for camera control
    public renderer?: GameRenderer;

    public isRunning: boolean = false;
    public timeScale: number = 1.0;
    public battleTime: number = 0;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    // Subsystems
    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();

        this.map.randomizeEnvironment(this);
    }

    // --- Passthroughs ---

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }

    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // --- Core Logic Control ---

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }

        this.agentMap.clear();

        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); // Use New Data-Driven AI System
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.agentMap.clear();

        this.agents.forEach(a => {
            a.reset(this.mapConfig);

            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });

            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });

        this.combat.projectiles = []; 
        this.events = []; 
        this.battleTime = 0;
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.combat.projectiles = [];
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    // --- Main Game Loop ---

    tick(dt: number) {
        if (!this.isRunning) return;

        this.events.length = 0;

        this.updateDirector(dt);

        // Win Condition Check
        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }
        if (blue === 0 && red > 0) { 
            this.stop(); 
            this.bus.emit('GAME_OVER', { winner: Team.RED });
        }
        else if (red === 0 && blue > 0) { 
            this.stop(); 
            this.bus.emit('GAME_OVER', { winner: Team.BLUE });
        }

        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            this.movement.updatePhysics(a, dt, this);

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            this.status.update(a, dt, this);

            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    // --- Loop Sub-Methods ---

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        const current = this.agents.find(a => a.id === this.directorTargetId);
        if (!current || current.hp <= 0) {
            this.directorTimer = -1;
        }

        if (this.directorTimer <= 0) {
            const alive = this.agents.filter(a => a.hp > 0);
            if (alive.length > 0) {
                const ultCasters = alive.filter(a => a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT');
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0;
                     return;
                }

                this.directorTargetId = alive[Math.floor(Math.random() * alive.length)].id;
                this.directorTimer = 3.0;
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 

            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, 'CAST', '詠唱', targetName, `開始引導 ${a.skills[i]!.name} (需 ${a.skills[i]!.cast} 秒)`);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    log(agent: Agent | null, typeOrAction: LogActionType | string, actionNameOrTarget: string | null, detailOrTargetInfo: string, legacyDetail?: string) {
        const time = this.battleTime.toFixed(1);

        let actionType: LogActionType = 'SYSTEM';
        let actionName = 'Action';
        let targetInfo = '';
        let detail = '';
        let color = LOG_COLORS.SYSTEM;

        const isLegacy = !this.isLogActionType(typeOrAction);

        if (isLegacy) {
            const rawAction = typeOrAction as string;
            actionName = rawAction;
            targetInfo = actionNameOrTarget || '';
            detail = detailOrTargetInfo;

            if (rawAction === '死亡') { actionType = 'DEATH'; color = LOG_COLORS.DEATH; }
            else if (rawAction === '放逐結束') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '中斷') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '命中') { actionType = 'HIT'; color = LOG_COLORS.HIT; }
            else { actionType = 'SYSTEM'; }
        } else {
            actionType = typeOrAction as LogActionType;
            actionName = actionNameOrTarget || '';
            targetInfo = detailOrTargetInfo || '';
            detail = legacyDetail || '';

            switch(actionType) {
                case 'MOVE': color = LOG_COLORS.MOVE; break;
                case 'CAST': color = LOG_COLORS.CAST; break;
                case 'HIT': color = LOG_COLORS.HIT; break;
                case 'HEAL': color = LOG_COLORS.HEAL; break;
                case 'DECISION': color = LOG_COLORS.DECISION; break;
                case 'DEATH': color = LOG_COLORS.DEATH; break;
                case 'CC': color = LOG_COLORS.CC; break;
                default: color = LOG_COLORS.SYSTEM; break;
            }
        }

        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            turn: Math.floor(this.battleTime * 10),
            agentId: agent?.id || 'SYSTEM',
            team: agent?.team,
            location: agent ? `(${agent.q},${agent.r})` : 'global',
            actionType: actionType,
            actionName: actionName,
            targetInfo: targetInfo,
            detail: detail,
            visualColor: color,
            action: actionName,
            target: targetInfo,
            loc: agent ? `@(${agent.q},${agent.r})` : ''
        };

        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }

    private isLogActionType(val: any): val is LogActionType {
        return ['MOVE','CAST','HIT','DECISION','DEATH','SYSTEM','HEAL','CC'].includes(val);
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // Speed of animation Adjusted: 0.4 for slower, majestic float (approx 2.5s duration)
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.4);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - Liquid Glass Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-md w-full">
                        <h2 className={`text-6xl font-black mb-2 tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_20px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.6)]'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <div className="h-1 w-20 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <button onClick={rematch} className="liquid-btn px-10 py-4 rounded-full text-xl font-bold bg-white/10 hover:bg-white/20 border-white/20 text-white shadow-lg w-full">
                            再戰一局
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );

        // Trigger Soft Camera Focus for Ultimates
        events.forEach(e => {
            if (e.type === 'CAST_START' && e.skill?.tag === 'ULT') {
                const target = engine.agents.find(a => a.id === e.targetId);
                if (target) {
                    this.camera.setInterestPoint(target.px, target.py, 2.5);
                } else if (e.pos) {
                    this.camera.setInterestPoint(e.pos.x, e.pos.y, 2.5);
                }
            }
        });
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Pass mapConfig AND mapKeys to calculate correct center
        this.camera.sync(camera, engine.mapConfig, engine.mapKeys); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER ---
        // Everything drawn so far (Scene) will be processed.
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: any) {
        // --- 1. Draw Trail ---
        const p = op.proj;
        if (p && p.trail.length > 1) {
            ctx.save();
            if (op.pSkillVis === 'ARROW') {
                ctx.beginPath();
            }
            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const altitude = op.pVisShadowY - op.pVisY;
        if (altitude > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - altitude/400);
            ctx.scale(shadowScale, shadowScale);
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);
        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        if (!width || !height || width <= 0 || height <= 0) return;

        // --- BOUNDING BOX CALCULATION ---
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Adjust bounds based on Hex size
            const halfW = 20; // Approx half width

            if (p.x - halfW < minX) minX = p.x - halfW;
            if (p.x + halfW > maxX) maxX = p.x + halfW;

            // Visual Top (includes block height)
            // Note: In screen coords, Y decreases as we go up.
            // p.y is the "ground floor" center. The block extends UP by `h`.
            // And maybe a bit more for the surface.
            const visualTop = p.y - h - BLOCK_HEIGHT; 
            const visualBottom = p.y + BLOCK_HEIGHT/2;

            if (visualTop < minY) minY = visualTop;
            if (visualBottom > maxY) maxY = visualBottom;

            count++;
        });

        // Fallback if map is empty
        if (count === 0) {
            const centerHex = { q: Math.floor(engine.mapConfig.w / 2), r: Math.floor(engine.mapConfig.h / 2) };
            const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
            minX = maxX = p.x;
            minY = maxY = p.y;
        }

        const mapCenterX = (minX + maxX) / 2;
        const mapCenterY = (minY + maxY) / 2;

        // Visual Correction:
        // Center the calculated bounding box on screen.
        // Camera (0,0) is screen center.
        // Camera Position (x,y) is the point in world space that is mapped to screen center.
        // So we just set camera x,y to the map center.

        // No extra offset needed if bounding box is correct.

        camera.current.x = mapCenterX;
        camera.current.y = mapCenterY;

        // SNAP LOGIC
        engine.renderer?.camera.snapTo(camera.current.x, camera.current.y, camera.current.zoom);

    }, [engine.mapConfig, engine.mapKeys]);

    const pan = useCallback((dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        if (dx === 0 && dy === 0) return;

        camera.current.x += dx / camera.current.zoom;
        camera.current.y += dy / camera.current.zoom;
    }, []);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    }, []);

    const getScreenCoords = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    }, []);

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom, 
        getScreenCoords
    };
};

import { MapConfig, HexUtils } from "../utils";

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current Visual State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (The "Attractor")
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // Cinematic State
    private interestX: number | null = null;
    private interestY: number | null = null;
    private interestTimer: number = 0;

    // Damping: Higher = Snappier (Less "floaty")
    private readonly PAN_DAMPING = 8.0; 
    private readonly ZOOM_DAMPING = 5.0;

    // Trauma System
    private trauma: number = 0;
    private maxShakeOffset: number = 2.0;   // Drastically reduced from 5.0
    private maxShakeAngle: number = 0.002;  // Drastically reduced from 0.01

    private currentShakeX: number = 0;
    private currentShakeY: number = 0;
    private currentShakeRot: number = 0;

    constructor() {}

    // Force immediate snap (used on init/resize)
    public snapTo(x: number, y: number, zoom: number) {
        this.x = x;
        this.y = y;
        this.zoom = zoom;
        this.targetX = x;
        this.targetY = y;
        this.targetZoom = zoom;
    }

    public sync(camera: Camera, mapConfig: MapConfig, mapKeys: Set<string>) {
        // If user is manually interacting (inputs changing), cancel cinematic
        const dist = Math.abs(camera.x - this.targetX) + Math.abs(camera.y - this.targetY);
        const isUserMoving = dist > 10; // Threshold

        if (isUserMoving) {
            this.interestTimer = 0; // Cancel cinematic
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
        } else if (this.interestTimer > 0 && this.interestX !== null && this.interestY !== null) {
            // --- CINEMATIC GENTLE DRIFT ---
            // Don't center perfectly on the action, just drift slightly towards it

            const center = this.getMapCenter(mapConfig, mapKeys);

            // Bias: 80% Map Center, 20% Action Point
            const bias = 0.2;
            const destX = center.x + (this.interestX - center.x) * bias;
            const destY = center.y + (this.interestY - center.y) * bias;

            this.targetX = destX - (100 / this.zoom); 
            this.targetY = destY;
            this.targetZoom = Math.max(camera.zoom, 1.2); 
        } else {
            // Default: Sync with React State (User Inputs)
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
        }
    }

    // NEW: Calculate true visual center of the existing map tiles
    public getMapCenter(mapConfig: MapConfig, mapKeys: Set<string>) {
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, mapConfig);
            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (p.y < minY) minY = p.y;
            if (p.y > maxY) maxY = p.y;
            count++;
        });

        if (count === 0) return { x: 0, y: 0 };

        return {
            x: (minX + maxX) / 2,
            y: (minY + maxY) / 2
        };
    }

    public setInterestPoint(x: number, y: number, duration: number = 1.5) {
        // Only set interest if not already shaking heavily (combat chaos)
        if (this.trauma < 0.3) {
            this.interestX = x;
            this.interestY = y;
            this.interestTimer = duration;
        }
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        if (this.interestTimer > 0) this.interestTimer -= dt;

        // Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 2.0);
        }

        // Calculate Shake
        const shakeFactor = this.trauma * this.trauma;
        this.currentShakeX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;

        // Smooth Damping
        const panFactor = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomFactor = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panFactor;
        this.y += (this.targetY - this.y) * panFactor;
        this.zoom += (this.targetZoom - this.zoom) * zoomFactor;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) {
        const cx = canvasWidth / 2;
        const cy = canvasHeight / 2;

        // 1. Shake
        ctx.translate(this.currentShakeX, this.currentShakeY);

        // 2. Rotation (Only at high trauma)
        if (this.trauma > 0.5) {
            ctx.translate(cx, cy);
            ctx.rotate(this.currentShakeRot);
            ctx.translate(-cx, -cy);
        }

        // 3. Camera
        // Pivot around screen center
        ctx.translate(cx, cy);
        ctx.scale(this.zoom, this.zoom);
        ctx.translate(-this.x, -this.y);
    }
}

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        if (!width || !height || width <= 0 || height <= 0) return;

        // --- BOUNDING BOX CALCULATION ---
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Adjust bounds based on Hex size
            const halfW = 20; // Approx half width

            if (p.x - halfW < minX) minX = p.x - halfW;
            if (p.x + halfW > maxX) maxX = p.x + halfW;

            // Visual Top (includes block height)
            // Note: In screen coords, Y decreases as we go up.
            // p.y is the "ground floor" center. The block extends UP by `h`.
            // And maybe a bit more for the surface.
            const visualTop = p.y - h - BLOCK_HEIGHT; 
            const visualBottom = p.y + BLOCK_HEIGHT/2;

            if (visualTop < minY) minY = visualTop;
            if (visualBottom > maxY) maxY = visualBottom;

            count++;
        });

        // Fallback if map is empty
        if (count === 0) {
            const centerHex = { q: Math.floor(engine.mapConfig.w / 2), r: Math.floor(engine.mapConfig.h / 2) };
            const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
            minX = maxX = p.x;
            minY = maxY = p.y;
        }

        const mapCenterX = (minX + maxX) / 2;
        const mapCenterY = (minY + maxY) / 2;

        // Visual Correction:
        // Center the calculated bounding box on screen.
        // Camera (0,0) is screen center.
        // Camera Position (x,y) is the point in world space that is mapped to screen center.
        // So we just set camera x,y to the map center.

        // No extra offset needed if bounding box is correct.

        camera.current.x = mapCenterX;
        camera.current.y = mapCenterY;

        // SNAP LOGIC
        engine.renderer?.camera.snapTo(camera.current.x, camera.current.y, camera.current.zoom);

    }, [engine.mapConfig, engine.mapKeys]);

    const pan = useCallback((dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        if (dx === 0 && dy === 0) return;

        // Inverted Pan: Dragging right (dx > 0) should move map right.
        // To move map right, camera must move left (decrease X).
        camera.current.x -= dx / camera.current.zoom;
        camera.current.y -= dy / camera.current.zoom;
    }, []);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    }, []);

    const getScreenCoords = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    }, []);

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom, 
        getScreenCoords
    };
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    private _dangerZones = new Map<string, {color: string, progress: number, visual: string, state: 'ACTIVE' | 'BROKEN', fadeRatio: number}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    // RENAMED: Now expects World Coordinates (wx, wy)
    getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    // --- REFACTORED FOR RENDER POOLING ---
    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        // 1. Pre-calc Unit States
        engine.agents.forEach(a => {
            if (a.hp > 0 && a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        const currentRadius = Math.max(0.5, (s.aoeRadius || 1) * progress);
                        const potentialHexes = HexUtils.range(centerHex, s.aoeRadius || 1);

                        potentialHexes.forEach(h => {
                            if (HexUtils.dist(centerHex!, h) <= currentRadius) {
                                this._dangerZones.set(`${h.q},${h.r}`, {
                                    color: s.color, 
                                    progress: progress,
                                    visual: s.visual || 'BOLT',
                                    state: 'ACTIVE',
                                    fadeRatio: 1.0
                                });
                            }
                        });
                    }
                }
            }
            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        });

        // 2. Iterate Tiles & Obstacles
        const PROJ_LIGHT_RADIUS = 40; 
        const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // Shared Transition Math
            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (visualY > py + 800) continue;

            const k = `${q},${r}`;

            // --- SUBMIT OBSTACLE ---
            const obstacleType = engine.obstacles.get(k);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = visualY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Visual Y includes height and anchor offset for drawing
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // --- SUBMIT TERRAIN ---
            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            // Populate RenderOp for Terrain
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = visualY; 
            op.z = 0;

            op.tx = px; 
            op.ty = visualY; // Base Y
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q;
            op.tr = r;

            // Overlays
            op.oStatus = specialStatus;
            op.oDanger = dangerInfo;
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);
            op.oFlash = flash;
            op.oRange = isRange;
            op.oRangeCol = rangeColor;
            op.oHover = isHover;
            op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );

        // Trigger Soft Camera Focus for Ultimates
        events.forEach(e => {
            if (e.type === 'CAST_START' && e.skill?.tag === 'ULT') {
                const target = engine.agents.find(a => a.id === e.targetId);
                if (target) {
                    this.camera.setInterestPoint(target.px, target.py, 2.5);
                } else if (e.pos) {
                    this.camera.setInterestPoint(e.pos.x, e.pos.y, 2.5);
                }
            }
        });
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Pass mapConfig AND mapKeys to calculate correct center
        this.camera.sync(camera, engine.mapConfig, engine.mapKeys); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER ---
        // Everything drawn so far (Scene) will be processed.
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: any) {
        // --- 1. Draw Trail ---
        const p = op.proj;
        if (p && p.trail.length > 1) {
            ctx.save();
            if (op.pSkillVis === 'ARROW') {
                ctx.beginPath();
            }
            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const altitude = op.pVisShadowY - op.pVisY;
        if (altitude > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - altitude/400);
            ctx.scale(shadowScale, shadowScale);
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);
        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';

export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan, onCameraZoom 
    } = props;

    // --- State Refs (Mutable for Performance) ---
    const interactionMode = useRef<InteractionMode>('IDLE');
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Action Context Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);
    const lastPaintHex = useRef<string>("");

    // Config Refs (Sync with props to avoid stale closures in event listeners)
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // --- 1. HELPERS: Coordinate Mapping & Hit Testing ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const getWorldPos = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;

        // Correct Screen->World transform
        const wx = (sx - cx) / zoom + camX;

        // For Y, we need to account for terrain height if possible, but for dragging objects 
        // we essentially want the ground plane projection.
        // We do a best guess by checking what hex is under cursor.
        const hex = getHexFromCoords(sx, sy);
        let h = 0;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);

        // World Y (Visual top)
        const visualWy = (sy - cy) / zoom + camY;

        // The object's "ground" y is lower than visual y by height
        return { x: wx, y: visualWy + h };
    };

    const getHitAgent = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;

        // Correct World Coordinates of the mouse click
        const wx = (sx - cx) / zoom + camX;
        const wy = (sy - cy) / zoom + camY;

        // Painter's Algorithm Hit Test (Front units first)
        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            // Visual top of unit (approx)
            const visualY = a.py - h - 40; 
            return { agent: a, visualY, dist: Math.abs(wy - visualY) + Math.abs(wx - a.px) };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);

        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            // Hit box check (approx 70x80 box centered on visual center)
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    // --- 2. LOGIC: Action Execution ---

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;

        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
            return;
        }

        const existingAgent = engine.getAgentAt(h.q, h.r);
        if (tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            let agent: Agent | null = null;
            if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                // Assign random skills for draft role
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        }
    };

    // --- 3. EVENT HANDLERS (Unified Logic) ---

    const handleInputStart = (sx: number, sy: number, isRightClick: boolean) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        if (isRightClick) {
            interactionMode.current = 'PAN';
            return;
        }

        // 1. Hit Test Agent
        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            interactionMode.current = 'DOWN'; // Wait to see if drag or click
            return;
        }

        // 2. Editing Logic
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;

        // Safe hex check
        const h = getHexFromCoords(sx, sy);
        const hasHex = h && engine.isValid(h.q, h.r);

        if (isEditing && hasHex) {
            // Hit Obstacle?
            if (tool === ToolType.SELECT && engine.hasObstacle(h!.q, h!.r)) {
                const obsType = engine.obstacles.get(HexUtils.key(h!));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h!.q, originR: h!.r, px: 0, py: 0 };
                    interactionMode.current = 'DOWN';
                    return;
                }
            }
            // Paint Tool?
            if (tool !== ToolType.SELECT) {
                // Immediate paint on down for better feel
                executePaintAction(h!);
                interactionMode.current = 'PAINT';
                return;
            }
        }

        interactionMode.current = 'DOWN'; // Default to potential pan
    };

    const handleInputMove = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        // Cursor & Hover Logic
        if (cvs) {
            const { tool, winner } = configRef.current;
            const isEditing = !engine.isRunning && winner === null;
            const hitAgent = getHitAgent(sx, sy);

            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (isEditing && tool !== ToolType.SELECT) cvs.style.cursor = 'crosshair';
            else if (hitAgent) cvs.style.cursor = 'pointer';
            else cvs.style.cursor = 'default';
        }

        if (interactionMode.current === 'IDLE') return;

        const prev = lastPointerPos.current || { x: sx, y: sy };
        const dx = sx - prev.x;
        const dy = sy - prev.y;
        lastPointerPos.current = { x: sx, y: sy };

        // --- Active State Handling ---
        if (interactionMode.current === 'PAN') {
            onCameraPan(dx, dy);
            return;
        }
        if (interactionMode.current === 'PAINT') {
            if (h && engine.isValid(h.q, h.r)) executePaintAction(h);
            return;
        }
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPos(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }
        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPos(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        // --- State Transition (Threshold Check) ---
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 8) {
                const { tool, winner } = configRef.current;
                const isEditing = !engine.isRunning && winner === null;

                if (isEditing && pressedAgentRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; // Lift
                    onSelect(pressedAgentRef.current);
                } else if (isEditing && draggedObstacleRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    // Remove from grid temporarily
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    const wPos = getWorldPos(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                } else {
                    interactionMode.current = 'PAN';
                    onCameraPan(dx, dy);
                }
            }
        }
    };

    const handleInputEnd = (sx: number, sy: number) => {
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        // Click Logic (Released without dragging)
        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (isEditing && tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (isEditing && h && engine.hasObstacle(h.q, h.r) && tool === ToolType.DELETE) {
                engine.removeObstacle(h.q, h.r);
            } else if (!pressedAgentRef.current) {
                onSelect(null);
            }
        }

        // Drop Logic
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, agent.id, agent.movementType);

            if (valid && h) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else {
                // Revert
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);
            if (valid && h) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); // Revert
        }

        // Reset
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
    };

    // --- 4. BINDINGS ---

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        // --- Mouse ---
        const onMouseDown = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputStart(e.clientX - rect.left, e.clientY - rect.top, e.button === 2);
        };
        const onMouseMove = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputMove(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseUp = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputEnd(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };
        const onCtx = (e: MouseEvent) => e.preventDefault();

        // --- Touch ---
        const getTouchPos = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };
        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputStart(x, y, false);
            } else if (e.touches.length === 2) {
                const t1 = getTouchPos(e.touches[0]);
                const t2 = getTouchPos(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE'; 
            }
        };
        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputMove(x, y);
            } else if (e.touches.length === 2) {
                const t1 = getTouchPos(e.touches[0]);
                const t2 = getTouchPos(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    onCameraZoom((dist - lastPinchDist.current) * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };
        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && e.touches.length === 0) {
                const { x, y } = getTouchPos(e.changedTouches[0]);
                handleInputEnd(x, y);
            }
            if (e.touches.length < 2) lastPinchDist.current = 0;
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchEnd);
        };
    }, []);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef: hoveredHexRef
    };
};

import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number) {
        // Ensure strictly integer dimensions to avoid sub-pixel blurring
        const w = Math.floor(width);
        const h = Math.floor(height);

        // Resize buffer if needed
        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }

        // SAVE STATE: We are likely in a DPR-scaled context
        ctx.save();

        // RESET TRANSFORM: We want to work in pure physical pixels 1:1
        // This eliminates any "Ghosting" caused by slight offsets in scale or translation
        ctx.resetTransform();

        // 1. Copy current frame to buffer
        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // 2. Chromatic Aberration (Significantly Toned Down)
        if (trauma > 0.1) {
            const offset = Math.floor(trauma * 4); // Smaller offset

            if (offset > 0) {
                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = 0.3 * trauma;

                // Red Channel Shift
                ctx.drawImage(this.tempCanvas, -offset, 0);

                // Blue Channel Shift
                ctx.drawImage(this.tempCanvas, offset, 0);

                ctx.restore();
            }
        }

        // 3. Bloom / Glow (Optimized)
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        // Very subtle bloom to avoid "Double Vision"
        ctx.globalAlpha = 0.1; 
        ctx.drawImage(this.tempCanvas, 0, 0);

        // High intensity bloom only on high trauma
        if (trauma > 0.5) {
            ctx.globalAlpha = 0.2 * trauma;
            ctx.drawImage(this.tempCanvas, 0, 0);
        }
        ctx.restore();

        // 4. Vignette (Dark corners)
        ctx.save();
        ctx.globalCompositeOperation = 'multiply';
        const rad = Math.max(w, h) * 0.8;
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.6, w/2, h/2, rad);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,10,20,0.5)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();

        // 5. White Flash (Explosion impact)
        if (trauma > 0.8) {
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = `rgba(255,255,255,${(trauma - 0.8)})`;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        // RESTORE STATE: Go back to DPR scaled context for UI drawing
        ctx.restore();
    }
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent, // Direct reference check
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;
        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); // Base Position (Ground)
        ctx.scale(scaleFactor, scaleFactor);

        // Physics values scaled
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- 1. DRAW BASE (Solid physical object on Ground) ---
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);

            // Draw The Heavy Base
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 
            ctx.restore();

            // Flying Tether (If flying)
            if (agent.movementType === MovementType.FLYING) {
                drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            // Ground Rune (If Casting)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
        }

        // --- 2. PREPARE BODY TRANSFORM (The Projection) ---
        // Move to physics offset (X, Y) and apply Lift (Z)
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        // Vertical Float Animation
        let bodyFloat = -UNIT_BODY_OFFSET; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat -= Math.sin(globalTime * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat -= Math.sin(globalTime * 4) * 2;
        }

        ctx.translate(0, bodyFloat);

        // Spawn Animation
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 

            spawnAlpha = eased;
            whiteOverlay = 1 - eased; 

            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit/Death Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        // Flight Thrusters
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // Silhouette Setup
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // --- 3. DRAW BODY ---
        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, globalTime, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, globalTime, isSilhouette);
            }

            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, globalTime);
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // --- 4. STATUS & UI ---
        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);
        }

        ctx.restore(); // Undo Body Transform

        // --- SELECTION BRACKET REMOVED FROM HERE ---
        // Moved to TacticalRenderer for clean Overlay drawing

        // Spawn Role Icon
        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Camera } from "../renderer"; 
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { Team, Role } from "../../types";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";

export interface RenderCamera {
    x: number;
    y: number;
    zoom: number;
}

const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class TacticalRenderer {
    // Hologram Glitch State
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    public update(dt: number, engine: GameEngine) {
        // Hologram Glitch Logic
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; // Trigger glitch for 0.3s
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;
    }

    public drawOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null, grid: GridSystem, globalTime: number) {
        ctx.save();

        // A. Selection Bracket (Moved from UnitRenderSystem for crispness)
        if (highlight && highlight.hp > 0) {
            const hH = grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const visualY = highlight.py - hH; // Ground

            // Calculate Scale Factor (Same logic as UnitRenderSystem)
            const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;
            let roleScaleMod = 1.0;
            switch(highlight.role) {
                case Role.TANK: roleScaleMod = 1.25; break; 
                case Role.WARRIOR: roleScaleMod = 1.1; break; 
                case Role.RANGER: roleScaleMod = 0.9; break; 
                case Role.MAGE: roleScaleMod = 0.9; break; 
                case Role.SUPPORT: roleScaleMod = 0.95; break;
            }
            const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

            ctx.save();
            ctx.translate(highlight.px, visualY);
            ctx.scale(scaleFactor, scaleFactor);

            // Move up to "center" of unit height for bracket
            const centerHeight = 50;
            ctx.translate(0, -centerHeight); 

            // 1. Rotating Brackets (Reticle)
            const bracketSize = 60;
            ctx.rotate(globalTime * 0.5);
            ctx.lineWidth = 3 / scaleFactor; // Compensate scale
            ctx.strokeStyle = '#22d3ee'; // Bright Cyan
            ctx.shadowColor = '#06b6d4';
            ctx.shadowBlur = 10;

            const cornerLen = Math.PI / 3;
            for(let i=0; i<4; i++) {
                ctx.beginPath();
                ctx.arc(0, 0, bracketSize, i * (Math.PI/2) - cornerLen/2, i * (Math.PI/2) + cornerLen/2);
                ctx.stroke();
            }

            // 2. Counter-Rotating Inner Ring
            ctx.rotate(-globalTime * 1.5);
            ctx.lineWidth = 1 / scaleFactor;
            ctx.setLineDash([5, 5]);
            ctx.beginPath();
            ctx.arc(0, 0, bracketSize * 0.85, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);

            // 3. Floating Arrow (Bounce) - Needs to be un-rotated
            ctx.restore(); // Back to Ground

            ctx.save();
            ctx.translate(highlight.px, visualY);
            ctx.scale(scaleFactor, scaleFactor);

            const bounce = Math.sin(globalTime * 8) * 8;
            const arrowHeight = 110;
            ctx.translate(0, -arrowHeight + bounce);

            ctx.fillStyle = '#22d3ee';
            ctx.shadowColor = '#06b6d4';
            ctx.shadowBlur = 15;

            // Arrow Down Shape
            ctx.beginPath();
            ctx.moveTo(-10, -15); 
            ctx.lineTo(10, -15);
            ctx.lineTo(0, 5);
            ctx.closePath();
            ctx.fill();

            // Glow Dot
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -22, 3, 0, Math.PI*2); ctx.fill();

            ctx.restore();
        }

        // B. Selected Agent Details (Path & Targets)
        if (highlight && highlight.hp > 0) {
            const hH = grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; // Waist height

            // 1. Movement Trajectory
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);

                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = grid.getTerrainHeight(hex.q, hex.r, engine);
                    ctx.lineTo(p.x, p.y - h - 30);
                });

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); // Dashed Line
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); // Reset
                ctx.globalAlpha = 1.0;

                // Destination Marker
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = grid.getTerrainHeight(dest.q, dest.r, engine);

                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }

            // 2. Target Line
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = grid.getTerrainHeight(t.q, t.r, engine);
                const endPx = t.px;
                const endPy = t.py - tH - 30;

                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';

                grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade out near source
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);

                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);

                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(globalTime * 10) * 0.2; // Pulse
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }

        ctx.restore();
    }

    public drawHUD(ctx: CanvasRenderingContext2D, engine: GameEngine, w: number, h: number, cam: RenderCamera, globalTime: number) {
        if (!engine.directorTargetId) return;
        const agent = engine.agents.find(a => a.id === engine.directorTargetId);
        if (!agent) return;

        // Position: Top Right, floating
        const hudX = w - 260; 
        const hudY = 60;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        let alphaMod = 1.0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 10;
            gy = (Math.random() - 0.5) * 5;
            alphaMod = 0.5 + Math.random() * 0.5;
            if (Math.random() > 0.8) alphaMod = 0.2; // Flicker out
        }

        // --- 2. Perspective Transform ---
        // matrix(1, 0, -0.15, 1, x, y)
        ctx.transform(1, 0, -0.15, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.globalAlpha = alphaMod;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = (0.5 + Math.sin(globalTime * 20) * 0.5) * alphaMod;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0 * alphaMod;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }

    public drawDebug(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        if (!width || !height || width <= 0 || height <= 0) return;

        // --- BOUNDING BOX CALCULATION ---
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        // 1. Terrain Bounds
        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            const halfW = 20;
            if (p.x - halfW < minX) minX = p.x - halfW;
            if (p.x + halfW > maxX) maxX = p.x + halfW;

            const visualTop = p.y - h - BLOCK_HEIGHT; 
            const visualBottom = p.y + BLOCK_HEIGHT/2;

            if (visualTop < minY) minY = visualTop;
            if (visualBottom > maxY) maxY = visualBottom;

            count++;
        });

        // 2. Unit Bounds (Important if units are flying or high up)
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            // Rough unit bounds
            if (a.px < minX) minX = a.px;
            if (a.px > maxX) maxX = a.px;

            // Account for height
            const h = engine.map.getTerrainHeight(a.q, a.r);
            const topY = a.py - h - 100; // Approx unit height
            if (topY < minY) minY = topY;
            if (a.py > maxY) maxY = a.py;
            count++;
        });

        // Fallback if map is empty
        if (count === 0) {
            const centerHex = { q: Math.floor(engine.mapConfig.w / 2), r: Math.floor(engine.mapConfig.h / 2) };
            const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
            minX = maxX = p.x;
            minY = maxY = p.y;
        }

        const mapCenterX = (minX + maxX) / 2;
        const mapCenterY = (minY + maxY) / 2;

        // Visual Correction:
        // Center the calculated bounding box on screen.
        camera.current.x = mapCenterX;
        camera.current.y = mapCenterY;

        // SNAP LOGIC
        engine.renderer?.camera.snapTo(camera.current.x, camera.current.y, camera.current.zoom);

    }, [engine.mapConfig, engine.mapKeys, engine.agents]); // Added agents to dependency to frame them if map is small

    const pan = useCallback((dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        if (dx === 0 && dy === 0) return;

        // Inverted Pan: Dragging right (dx > 0) should move map right.
        // To move map right, camera must move left (decrease X).
        camera.current.x -= dx / camera.current.zoom;
        camera.current.y -= dy / camera.current.zoom;
    }, []);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    }, []);

    const getScreenCoords = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    }, []);

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom, 
        getScreenCoords
    };
};

import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { Role } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 40;
const BAR_HEIGHT = 5;
const BAR_BORDER = 1;

interface FloatingText {
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt?: boolean; // New flag for Ultimate visuals
}

export class HUDSystem {
    damageNumbers: FloatingText[] = [];

    addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        // UX FIX: Prevent Kill Streak Overlap
        if (type === 'KILL_STREAK') {
            this.damageNumbers = this.damageNumbers.filter(d => d.type !== 'KILL_STREAK');
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; // Ults float very slowly
                life = 2.5; // Stay longer
                size = 24; // Bigger font
            } else {
                vy = -20; // Normal skills float gently
                life = 1.2;
                size = 14; // Smaller to be less intrusive
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; // Stay very long
            size = 32; // HUGE
        } else {
            // DAMAGE / HEAL
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; // Initial jump
        }

        this.damageNumbers.push({
            x, y,
            vx, vy, 
            text, 
            color, 
            life, 
            maxLife: life, 
            size,
            type,
            isUlt
        });
    }

    update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            // Physics integration
            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            // Gravity logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; // Friction
            } else if (d.type === 'KILL_STREAK') {
                // Anti-gravity float for Kill Streaks
                d.vy *= 0.92; // Slow down to a halt
            }

            if (d.life <= 0) {
                this.damageNumbers.splice(i, 1); 
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig) {
        // 1. Draw HP/MP Bars & Status Labels
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            // Determine Ground Level Logic
            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            this.drawUnitBars(ctx, a, headX, anchorY);
            // Replace text label with gauges
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        // 2. Draw Floating Text
        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        // --- PRIORITY SYSTEM FOR STATUS DISPLAY ---
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH';
                gaugeColor = '#d8b4fe'; // Pink/Purple
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS';
                gaugeColor = '#facc15'; // Gold
            } else {
                iconType = 'BANISH';
                gaugeColor = '#7e22ce'; // Dark Purple
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN';
            gaugeColor = '#fbbf24'; // Amber/Yellow
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE';
            gaugeColor = '#94a3b8'; // Grey
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        const w = BAR_WIDTH;
        const h = BAR_HEIGHT;
        const b = BAR_BORDER;

        // Background (Black Border)
        ctx.fillStyle = '#000'; 
        ctx.fillRect(x - w/2 - b, y - b, w + b*2, h + b*2);

        // HP Fill
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        ctx.fillStyle = COLORS.HP; 
        ctx.fillRect(x - w/2, y, w * hpPct, h);

        // MP Bar (Only if unit uses MP)
        if (agent.maxMp > 0) {
            const mpH = h / 2 + 1;
            const mpY = y + h + b;

            ctx.fillStyle = '#000'; 
            ctx.fillRect(x - w/2 - b, mpY, w + b*2, mpH + b*2);

            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            ctx.fillStyle = COLORS.MP; 
            ctx.fillRect(x - w/2, mpY + b, w * mpPct, mpH);
        }
    }

    private drawCircularGauge(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        pct: number, 
        visualKey: string, 
        color: string, 
        isSkill: boolean
    ) {
        const radius = 14;
        const iconY = y - 18; 

        ctx.save();
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = '#1e293b';
        ctx.fill();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        if (icon) {
            ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        }
        ctx.restore();

        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(0, 0, 0, 0.6)';
        ctx.lineWidth = 4;
        ctx.stroke();

        const safePct = Math.max(0, Math.min(1, pct));

        if (safePct > 0) {
            ctx.beginPath();
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));

            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.stroke();
        }

        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)';
        ctx.lineWidth = 1;
        ctx.stroke();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; // RESET SHADOW

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);

                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);

                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                // Stroke (Sharp)
                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);

                // Fill
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);

                // No shadowBlur to avoid ghosting artifacts
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);

                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 30;
                    const h = d.size + 16;

                    const bgGrad = ctx.createLinearGradient(-w, 0, w, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.6)'); 
                    bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.6)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w, -h/2, w*2, h);

                    ctx.fillStyle = '#fff';
                    ctx.strokeStyle = '#000';
                    ctx.lineWidth = 3;

                    ctx.strokeText(d.text, 0, 0);
                    ctx.fillText(d.text, 0, 0);

                    ctx.restore();

                } else {
                    ctx.font = `bold italic ${d.size}px "Segoe UI", sans-serif`;
                    ctx.lineWidth = 3;
                    ctx.lineJoin = 'round';
                    ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)'; 
                    ctx.strokeText(d.text, d.x, d.y);
                    ctx.fillStyle = d.color;
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else if (d.type === 'CC') {
                ctx.font = `900 ${d.size}px "Arial Black", sans-serif`; 
                ctx.strokeStyle = 'rgba(0,0,0,1.0)';
                ctx.lineWidth = 3;
                ctx.strokeText(d.text, d.x, d.y);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, d.x, d.y);

            } else {
                // DAMAGE / HEAL
                ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                ctx.fillStyle = d.color; 
                ctx.strokeStyle = 'rgba(0,0,0,0.8)'; 
                ctx.lineWidth = 3; 
                ctx.strokeText(d.text, d.x, d.y); 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

