import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );

        // Trigger Soft Camera Focus for Ultimates
        events.forEach(e => {
            if (e.type === 'CAST_START' && e.skill?.tag === 'ULT') {
                const target = engine.agents.find(a => a.id === e.targetId);
                if (target) {
                    this.camera.setInterestPoint(target.px, target.py, 2.5);
                } else if (e.pos) {
                    this.camera.setInterestPoint(e.pos.x, e.pos.y, 2.5);
                }
            }
        });
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Pass mapConfig AND mapKeys to calculate correct center
        this.camera.sync(camera, engine.mapConfig, engine.mapKeys); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER ---
        // Everything drawn so far (Scene) will be processed.
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Draw Trail ---
        // Using the pre-calculated visual trail points in op.pTrail
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = op.pColor;

            // Trail Width Logic: Tapering
            // We iterate through the visual points (Screen Space relative to map origin)
            // BUT our context is currently translated to the CAMERA transform only.
            // Wait, RenderOp draw loop does NOT translate to op.tx, op.ty for Projectiles?
            // The switch case calls `drawProjectile(ctx, op)` without translation.
            // Correct.

            // Draw the line strip
            ctx.beginPath();

            const trail = op.pTrail;
            if (trail.length > 0) {
                // The first point in trail array is the HEAD (newest)
                ctx.moveTo(trail[0].x, trail[0].y);
                for(let i=1; i<trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
            }

            // Style: Fade out
            const grad = ctx.createLinearGradient(trail[0].x, trail[0].y, trail[trail.length-1].x, trail[trail.length-1].y);
            grad.addColorStop(0, op.pColor); // Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Tail

            ctx.strokeStyle = grad;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();

            // Inner Core Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        // Simple blob shadow on ground
        // We use pVisShadowY stored in op
        const shadowAltitude = op.pVisShadowY - op.pVisY; // Difference between ground and air

        // Don't draw shadow if too low (to avoid clipping with sprite)
        // Or if really high, shadow fades
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            // Scale shadow based on height (higher = smaller/blurrier)
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);

            ctx.scale(shadowScale, shadowScale * 0.5); // Flattened ellipse
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion) - Cleaner ellipse
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        ctx.ellipse(cx, cy - 2, 28, 14, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Clean Geometric Layers) ---

            // Trunk
            ctx.fillStyle = '#291815'; // Darker Wood
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy); 
            ctx.lineTo(cx + 6, cy);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                // const nextY = topY + (bottomY - topY) * ((i+1)/layers);
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); // Bright Tip
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); // Dark Bottom

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                // Left Flare
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                // Bottom Curve (Concave up)
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                // Right Flare
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                // Edge Highlight (Rim)
                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();

                // Shadow underneath layer
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.beginPath();
                ctx.moveTo(cx, layerY + 10);
                ctx.lineTo(cx + spread, layerY + 15);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.fill();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---

            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Facet 1 (Left/Dark)
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Facet 2 (Right/Light)
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();

                ctx.restore();
            };

            drawCrystal(cx - 15, cy - 5, 10, 40, -0.2, '#fff');
            drawCrystal(cx + 12, cy, 12, 35, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 16, 65, 0, '#fff'); // Main

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Dark Geometric) ---

            const topY = cy - 75;
            const w = 25;

            // Main Body Gradient
            const rockGrad = ctx.createLinearGradient(cx - w, topY, cx + w, cy);
            rockGrad.addColorStop(0, style.light);
            rockGrad.addColorStop(0.4, style.main);
            rockGrad.addColorStop(1, style.dark);
            ctx.fillStyle = rockGrad;

            ctx.beginPath();
            ctx.moveTo(cx, topY); // Top tip
            ctx.lineTo(cx + w, cy - 20); // Right mid
            ctx.lineTo(cx + 10, cy); // Base Right
            ctx.lineTo(cx - 10, cy); // Base Left
            ctx.lineTo(cx - w, cy - 20); // Left mid
            ctx.closePath();
            ctx.fill();

            // Facet Highlights (Edges)
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx - w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy); // Center spine
            ctx.stroke();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 5, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else if (styleKey === 'SANDSTONE') {
            // --- MESA STACK (Rounded Layers) ---

            const layers = 5;
            const w = 35;
            let currentW = w;
            let currentY = cy;

            for(let i=0; i<layers; i++) {
                const h = 15 + Math.random() * 5;
                const nextY = currentY - h;
                const nextW = currentW * (0.6 + Math.random() * 0.2); // Taper up

                // Gradient for rounded volume
                const grad = ctx.createLinearGradient(cx - currentW, 0, cx + currentW, 0);
                const color = i % 2 === 0 ? style.main : style.light;
                grad.addColorStop(0, style.dark);
                grad.addColorStop(0.2, color);
                grad.addColorStop(0.8, color);
                grad.addColorStop(1, style.dark);
                ctx.fillStyle = grad;

                ctx.beginPath();
                ctx.ellipse(cx, currentY, currentW, 10, 0, 0, Math.PI*2);
                ctx.fill();

                // Block body
                ctx.fillRect(cx - nextW, nextY, nextW * 2, currentY - nextY);

                // Top Highlight Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.5;
                ctx.beginPath(); ctx.ellipse(cx, nextY, nextW, 6, 0, 0, Math.PI*2); ctx.stroke();
                ctx.globalAlpha = 1.0;

                currentY = nextY;
                currentW = nextW;
            }
            // Top Cap
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.ellipse(cx, currentY, currentW, 6, 0, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- STONE PILLAR (Stylized Fortification) ---
            const w = 30; // Half width
            const h = 60; // Height
            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10); // Isometric top-right
            ctx.lineTo(cx + w, cy - 10);   // Bottom-right
            ctx.lineTo(cx, cy);            // Bottom-center
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 10);
            ctx.lineTo(cx - w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx, topY + 20); // Center-down
            ctx.lineTo(cx - w, topY + 10);
            ctx.fill();

            // 4. Edges / Outline
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;

            ctx.beginPath();
            // Central Spine
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy);
            // Top Diamond
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, topY + 10); ctx.lineTo(cx, topY + 20); ctx.lineTo(cx - w, topY + 10); ctx.lineTo(cx, topY);
            ctx.stroke();

            // Rivet Details
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, topY + 30, 3, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }
};

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";

export class BackgroundRenderer {

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Base Gradient & Complex Background
        this.drawComplexBackground(ctx, width, height, scene, globalTime);

        // 2. Atmospheric Fog (Screen Space overlay)
        // Map dimensions in pixels for fog scrolling
        const mapPxW = mapConfig.w * HEX_SIZE * 2;
        const mapPxH = mapConfig.h * HEX_SIZE * 2;
        this.drawAtmosphericFog(ctx, mapPxW, mapPxH, scene, globalTime);

        // 3. Vignette (Focus attention on center)
        const rad = Math.min(width, height) * 0.8;
        const vig = ctx.createRadialGradient(width/2, height/2, rad * 0.5, width/2, height/2, rad * 1.5);
        vig.addColorStop(0, 'transparent');
        vig.addColorStop(1, 'rgba(0,0,0,0.5)'); // Reduced opacity to let colors shine
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, width, height);
    }

    private drawComplexBackground(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number): void {
        // 1. Base Gradient (Sky + Horizon)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background); // Sky Top
        bgGrad.addColorStop(0.5, scene.horizon);  // Horizon Line
        bgGrad.addColorStop(1, '#020617');        // Ground Blend (Dark)
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        ctx.save();

        // 1.5 Horizon Glow (Bloom)
        const hY = h * 0.6;
        const hGlow = ctx.createRadialGradient(w/2, hY, w*0.1, w/2, hY, w*0.8);
        hGlow.addColorStop(0, scene.horizon);
        hGlow.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;
        ctx.fillStyle = hGlow;
        ctx.fillRect(0, 0, w, h);
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;

        // 2. Dynamic Moving Clouds (Parallax Layers)
        if (scene.id !== 'VOID') {
            this.drawMovingClouds(ctx, w, h, scene, t);
        }

        // 3. Stars / Nebula (For Space/Ice/Night themes)
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             // Nebula clouds
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.15;
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }

             // Stars
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8; // Keep stars in upper sky
                 const size = Math.random() * 2;
                 const alpha = Math.sin(t + i) * 0.5 + 0.5;
                 ctx.globalAlpha = alpha * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 4. Distant Silhouette (Mountains) - Filled Polygon for depth
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';

            const drawMountainLayer = (speed: number, yOffset: number, color: string, roughness: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const n = Math.sin(x * 0.01 + t * speed) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.55 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };

            // Far Layer (Lighter/Foggy)
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0.005, 0, scene.fogColor, 60);

            // Near Layer (Darker)
            ctx.globalAlpha = 0.5;
            drawMountainLayer(0.01, 60, scene.horizon, 40);
        }

        // 5. Special Sky Features & God Rays
        this.drawGodRays(ctx, w, h, t);
        this.drawSkyFeatures(ctx, w, h, scene, t);

        ctx.restore();
    }

    private drawMovingClouds(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        // Multi-layered clouds
        const layers = 2;
        ctx.globalCompositeOperation = 'soft-light';
        ctx.fillStyle = scene.fogColor;

        for(let l=0; l<layers; l++) {
            const speed = (l + 1) * 10;
            const yBase = h * (0.1 + l * 0.2);
            const scale = 100 + l * 50;

            ctx.globalAlpha = 0.1 + l * 0.1;

            for(let i=0; i<6; i++) {
                // Moving X
                const x = ((t * speed + i * (w/4)) % (w + scale*2)) - scale;
                const y = yBase + Math.sin(t * 0.5 + i) * 20;

                ctx.beginPath();
                ctx.ellipse(x, y, scale, scale * 0.4, 0, 0, Math.PI*2);
                ctx.fill();
            }
        }
    }

    private drawGodRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';

        // Source position moves slowly
        const sourceX = w * 0.8 + Math.sin(t * 0.1) * 100;
        const sourceY = -100;

        const grad = ctx.createRadialGradient(sourceX, sourceY, 50, sourceX, sourceY, w);
        grad.addColorStop(0, 'rgba(255, 255, 255, 0.15)'); 
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;

        // Draw Angular Rays
        for(let i=0; i<5; i++) {
            const angle = Math.PI / 2 + 0.3 + Math.sin(t * 0.05 + i) * 0.1 + (i * 0.15);
            const width = Math.PI / 32 * (1 + Math.sin(t + i)*0.2);
            const rayLen = w * 1.5;

            ctx.beginPath();
            ctx.moveTo(sourceX, sourceY);
            ctx.lineTo(sourceX + Math.cos(angle - width) * rayLen, sourceY + Math.sin(angle - width) * rayLen);
            ctx.lineTo(sourceX + Math.cos(angle + width) * rayLen, sourceY + Math.sin(angle + width) * rayLen);
            ctx.fill();
        }
        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            // --- COSMIC RIVER ---
            const color = scene.ambientColor; // Purple

            for(let i=0; i<5; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                for(let x=0; x<=w; x+=10) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6;
            for(let i=0; i<20; i++) {
                const prog = (t * 0.1 + i / 20) % 1;
                const x = prog * w;
                const y = h * 0.3 + 50 + Math.sin(x * 0.005 + t * 0.2) * 40;
                ctx.beginPath(); ctx.arc(x, y, Math.random()*2 + 1, 0, Math.PI*2); ctx.fill();
            }

        } else if (scene.bgFeature === 'AURORA') {
            const colors = ['#34d399', '#22d3ee', '#818cf8']; 

            for(let i=0; i<3; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;

                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); 
                ctx.lineTo(0, 0); 
                ctx.fill();
            }

        } else if (scene.bgFeature === 'HEAT_WAVE') {
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            for(let i=0; i<10; i++) {
                const x = (i / 10) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 10;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); 
        const numClouds = 8;

        for (let i = 0; i < numClouds; i++) {
            // Clouds moving diagonally
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        ctx.restore();
    }
}

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion) - Cleaner ellipse
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        ctx.ellipse(cx, cy - 2, 28, 14, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Clean Geometric Layers) ---

            // Trunk
            ctx.fillStyle = '#291815'; // Darker Wood
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy); 
            ctx.lineTo(cx + 6, cy);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                // const nextY = topY + (bottomY - topY) * ((i+1)/layers);
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); // Bright Tip
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); // Dark Bottom

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                // Left Flare
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                // Bottom Curve (Concave up)
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                // Right Flare
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                // Edge Highlight (Rim)
                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();

                // Shadow underneath layer
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.beginPath();
                ctx.moveTo(cx, layerY + 10);
                ctx.lineTo(cx + spread, layerY + 15);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.fill();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---

            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Facet 1 (Left/Dark)
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Facet 2 (Right/Light)
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();

                ctx.restore();
            };

            drawCrystal(cx - 15, cy - 5, 10, 40, -0.2, '#fff');
            drawCrystal(cx + 12, cy, 12, 35, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 16, 65, 0, '#fff'); // Main

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Dark Geometric) ---

            const topY = cy - 75;
            const w = 25;

            // Main Body Gradient
            const rockGrad = ctx.createLinearGradient(cx - w, topY, cx + w, cy);
            rockGrad.addColorStop(0, style.light);
            rockGrad.addColorStop(0.4, style.main);
            rockGrad.addColorStop(1, style.dark);
            ctx.fillStyle = rockGrad;

            ctx.beginPath();
            ctx.moveTo(cx, topY); // Top tip
            ctx.lineTo(cx + w, cy - 20); // Right mid
            ctx.lineTo(cx + 10, cy); // Base Right
            ctx.lineTo(cx - 10, cy); // Base Left
            ctx.lineTo(cx - w, cy - 20); // Left mid
            ctx.closePath();
            ctx.fill();

            // Facet Highlights (Edges)
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx - w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy); // Center spine
            ctx.stroke();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 5, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else if (styleKey === 'SANDSTONE') {
            // --- MESA STACK (Rounded Layers) ---

            const layers = 5;
            const w = 35;
            let currentW = w;
            let currentY = cy;

            for(let i=0; i<layers; i++) {
                const h = 15 + Math.random() * 5;
                const nextY = currentY - h;
                const nextW = currentW * (0.6 + Math.random() * 0.2); // Taper up

                // Gradient for rounded volume
                const grad = ctx.createLinearGradient(cx - currentW, 0, cx + currentW, 0);
                const color = i % 2 === 0 ? style.main : style.light;
                grad.addColorStop(0, style.dark);
                grad.addColorStop(0.2, color);
                grad.addColorStop(0.8, color);
                grad.addColorStop(1, style.dark);
                ctx.fillStyle = grad;

                ctx.beginPath();
                ctx.ellipse(cx, currentY, currentW, 10, 0, 0, Math.PI*2);
                ctx.fill();

                // Block body
                ctx.fillRect(cx - nextW, nextY, nextW * 2, currentY - nextY);

                // Top Highlight Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.5;
                ctx.beginPath(); ctx.ellipse(cx, nextY, nextW, 6, 0, 0, Math.PI*2); ctx.stroke();
                ctx.globalAlpha = 1.0;

                currentY = nextY;
                currentW = nextW;
            }
            // Top Cap
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.ellipse(cx, currentY, currentW, 6, 0, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- STONE PILLAR (Stylized Fortification) ---
            const w = 30; // Half width
            const h = 60; // Height
            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10); // Isometric top-right
            ctx.lineTo(cx + w, cy - 10);   // Bottom-right
            ctx.lineTo(cx, cy);            // Bottom-center
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 10);
            ctx.lineTo(cx - w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx, topY + 20); // Center-down
            ctx.lineTo(cx - w, topY + 10);
            ctx.fill();

            // 4. Edges / Outline
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;

            ctx.beginPath();
            // Central Spine
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy);
            // Top Diamond
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, topY + 10); ctx.lineTo(cx, topY + 20); ctx.lineTo(cx - w, topY + 10); ctx.lineTo(cx, topY);
            ctx.stroke();

            // Rivet Details
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, topY + 30, 3, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 20;

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Cluster of ice shards
        drawShard(cx - 20, cy, 15, 60, -0.3);
        drawShard(cx + 20, cy - 5, 18, 50, 0.3);
        drawShard(cx, cy + 10, 25, 90, 0); // Main center shard

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent, // Direct reference check
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;
        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); // Base Position (Ground)
        ctx.scale(scaleFactor, scaleFactor);

        // Physics values scaled
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- 1. DRAW BASE (Solid physical object on Ground) ---
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);

            // Draw The Heavy Base
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 
            ctx.restore();

            // Flying Tether (If flying)
            if (agent.movementType === MovementType.FLYING) {
                drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            // Ground Rune (If Casting)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
        }

        // --- 2. PREPARE BODY TRANSFORM (The Projection) ---
        // Move to physics offset (X, Y) and apply Lift (Z)
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        // Vertical Float Animation
        let bodyFloat = -UNIT_BODY_OFFSET; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat -= Math.sin(globalTime * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat -= Math.sin(globalTime * 4) * 2;
        }

        ctx.translate(0, bodyFloat);

        // Spawn Animation
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 

            spawnAlpha = eased;
            whiteOverlay = 1 - eased; 

            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit/Death Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        // Flight Thrusters
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // Silhouette Setup
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // --- 3. DRAW BODY ---
        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, globalTime, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, globalTime, isSilhouette);
            }

            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, globalTime);
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // --- 4. STATUS & UI ---
        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // Undo Body Transform

        // --- SELECTION BRACKET REMOVED FROM HERE ---
        // Moved to TacticalRenderer for clean Overlay drawing

        // Spawn Role Icon
        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

